) values
  ('IE:truck-driver','IE','truck-driver','Large goods vehicle drivers — professional HGV driver scope','SOC','SOC 2010','8211','EUR',true,'Road Safety Authority','https://www.rsa.ie/services/professional-drivers/cpc','profile_ready','2026-08-11',now()),
