  ('IE:commercial-pilot','IE','commercial-pilot','Aircraft pilots and flight engineers — commercial pilot scope','SOC','SOC 2010','3512','EUR',true,'Irish Aviation Authority','https://www.iaa.ie/personnel-licensing/pilot-licences-%28eu-regulations%29/commercial-pilot-license','profile_ready','2026-08-11',now()),
