insert into public.country_occupation_metric_snapshots (
  profile_key,as_of_date,employment_total,median_hourly_earnings,annualised_median_salary,
  shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,
  entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,
  opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at
) values
  ('IE:truck-driver','2026-08-11',null,null,null,20,0,0,0,12,0,0,6,0,38,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 8211 Large goods vehicle drivers, restricted to professional HGV driving rather than van/taxi/bus driving.','shortage_note','SOLAS National Skills Bulletin 2025 directly identifies HGV drivers as a current Transport and Logistics shortage; 20/20.','visa_basis','SOC 8211 is on the current Ineligible List except HGV drivers holding category CE or C1E, or an equivalent category recognised through an RSA mutual-recognition agreement. The qualifying exception is treated as conditional GEP access; 6/10.','entry_basis','Ireland has a structured RSA truck-licence and Driver CPC route; 12/15.','salary_method','No exact comparable current Irish occupation-level median salary series has been normalised; 0.','entry_burden_basis','Professional truck driving requires the applicable full licence and a valid Driver CPC card; regulated entry burden receives 0/5.'),'2026-08-11'),
  ('IE:logistics-coordinator','2026-08-11',null,null,null,0,0,0,0,10,0,0,6,5,21,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 4134 Transport and distribution clerks and assistants, logistics-coordinator scope.','shortage_note','SOLAS 2025 says shortage evidence for stock-control and transport/distribution administrative occupations is inconclusive because of small employment numbers; 0/20.','visa_basis','SOC 4134 is neither on the current Critical Skills List nor the current Ineligible List, so ordinary General Employment Permit treatment may apply subject to the Labour Market Needs Test and other requirements; 6/10.','entry_basis','FET, logistics/supply-chain training and workplace progression provide accessible routes; 10/15.','salary_method','No exact comparable current Irish occupation-level median salary series has been normalised; 0.','entry_burden_basis','No universal statutory personal registration requirement; 5/5.'),'2026-08-11'),
  ('IE:aircraft-maintenance-technician','2026-08-11',null,null,null,0,0,0,0,12,0,0,6,5,23,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5235 Aircraft maintenance and related trades, aircraft-maintenance technician scope.','shortage_note','No exact aircraft-maintenance shortage is published in the reviewed SOLAS 2025 Transport and Logistics shortage summary; 0/20.','visa_basis','SOC 5235 is neither on the current Critical Skills List nor the current Ineligible List, so ordinary General Employment Permit treatment may apply subject to current requirements; 6/10.','entry_basis','Aircraft Mechanics is a current Irish craft apprenticeship, giving a direct structured work-based route; 12/15.','licensing_boundary','IAA Part-66 Aircraft Maintenance Licences are required for applicable certifying privileges, but the broader technician occupation also includes work performed under appropriately authorised certifying staff, so universal personal registration is not asserted.','salary_method','No exact comparable current Irish occupation-level median salary series has been normalised; 0.','entry_burden_basis','No universal personal licence across every technician function; 5/5.'),'2026-08-11'),
  ('IE:commercial-pilot','2026-08-11',null,null,null,0,0,0,0,4,0,0,6,0,10,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 3512 Aircraft pilots and flight engineers, restricted to commercial pilot employment.','shortage_note','SOLAS 2025 Transport and Logistics does not identify commercial pilots as a current shortage in the reviewed summary; 0/20.','visa_basis','SOC 3512 is neither on the current Critical Skills List nor the current Ineligible List, so ordinary General Employment Permit treatment may apply subject to current requirements; 6/10.','entry_basis','Commercial flying requires approved flight training and substantial licence-specific training; 4/15.','licensing_boundary','The IAA states that commercial flying requires a commercial-level licence, normally a CPL or ATPL with the applicable Class 1 medical standard.','salary_method','No exact comparable current Irish occupation-level median salary series has been normalised; 0.','entry_burden_basis','Mandatory flight crew licensing and medical fitness create a high regulated entry burden; 0/5.'),'2026-08-11'),
  ('IE:marine-engineer','2026-08-11',null,null,null,0,0,0,0,8,0,0,6,0,14,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 3513 Ship and hovercraft officers, restricted to marine engineering officer duties and kept separate from shore-based Mechanical Engineer 2122.','shortage_note','SOLAS 2025 Transport and Logistics does not publish an exact Marine Engineer shortage in the reviewed summary; 0/20.','visa_basis','SOC 3513 is neither on the current Critical Skills List nor the current Ineligible List, so ordinary General Employment Permit treatment may apply subject to current requirements; 6/10.','entry_basis','Maritime engineering education, approved sea service and certification form a structured professional route; 8/15.','licensing_boundary','The Department of Transport states that seafaring is strictly regulated and issues Certificates of Competency for service on merchant ships and fishing vessels.','salary_method','No exact comparable current Irish occupation-level median salary series has been normalised; 0.','entry_burden_basis','Applicable seagoing engineering officer duties require the appropriate Certificate of Competency; 0/5.'),'2026-08-11'),
  ('IE:deck-officer','2026-08-11',null,null,null,0,0,0,0,8,0,0,6,0,14,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 3513 Ship and hovercraft officers, restricted to deck/navigation officer duties.','shortage_note','SOLAS 2025 Transport and Logistics does not publish an exact Deck Officer shortage in the reviewed summary; 0/20.','visa_basis','SOC 3513 is neither on the current Critical Skills List nor the current Ineligible List, so ordinary General Employment Permit treatment may apply subject to current requirements; 6/10.','entry_basis','Approved maritime education, sea service and competency examinations form the professional route; 8/15.','licensing_boundary','The Department of Transport states that seafaring is strictly regulated and Certificates of Competency are issued for service on merchant ships and fishing vessels.','salary_method','No exact comparable current Irish occupation-level median salary series has been normalised; 0.','entry_burden_basis','Applicable deck/navigation officer duties require the appropriate Certificate of Competency; 0/5.'),'2026-08-11'),
  ('IE:warehouse-manager','2026-08-11',null,null,null,0,0,0,0,8,0,0,6,5,19,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 1162 Managers and directors in storage and warehousing, genuine warehouse-management scope rather than elementary storage 9260 or fork-lift driving 8222.','shortage_note','SOLAS 2025 Transport and Logistics reports replacement demand and churn but does not publish an exact Warehouse Manager shortage; 0/20.','visa_basis','SOC 1162 is neither on the current Critical Skills List nor the current Ineligible List, so ordinary General Employment Permit treatment may apply subject to the Labour Market Needs Test and other requirements; 6/10.','entry_basis','Warehouse operations, logistics/supply-chain study and progression from supervisory roles are common routes; 8/15.','salary_method','No exact comparable current Irish occupation-level median salary series has been normalised; 0.','entry_burden_basis','No universal statutory personal registration requirement; 5/5.'),'2026-08-11'),
  ('IE:automotive-service-technician','2026-08-11',null,null,null,0,0,0,0,12,0,0,6,5,23,'career-opportunity-ie-v1','provisional',jsonb_build_object('classification_scope','SOC 2010 5231 Vehicle technicians, mechanics and electricians, restricted to car/motor mechanic and vehicle-service technician work.','shortage_note','The 2026 employment-permit review renewed quota access for Car/Motor Mechanic, Auto Electrician and Vehicle Technician, but permit policy is not converted into an exact SOLAS shortage signal; 0/20.','visa_basis','The 2026 occupations review renewed a General Employment Permit quota for Car/Motor Mechanic, Auto Electrician and Vehicle Technician, subject to a fresh Labour Market Needs Test and current quota/permit conditions; 6/10.','entry_basis','Motor Mechanics is a current Irish craft apprenticeship and provides a direct structured work-based route; 12/15.','salary_method','No exact comparable current Irish occupation-level median salary series has been normalised; 0.','entry_burden_basis','No universal statutory personal occupational licence is asserted for the broad automotive service technician scope; 5/5.'),'2026-08-11')
on conflict (profile_key,as_of_date) do update set
  employment_total=excluded.employment_total,median_hourly_earnings=excluded.median_hourly_earnings,annualised_median_salary=excluded.annualised_median_salary,
  shortage_component=excluded.shortage_component,vacancy_intensity_component=excluded.vacancy_intensity_component,employer_diversity_component=excluded.employer_diversity_component,vacancy_trend_component=excluded.vacancy_trend_component,
  entry_level_component=excluded.entry_level_component,salary_component=excluded.salary_component,growth_component=excluded.growth_component,visa_component=excluded.visa_component,entry_burden_component=excluded.entry_burden_component,
  opportunity_score=excluded.opportunity_score,score_methodology_version=excluded.score_methodology_version,score_status=excluded.score_status,score_evidence=excluded.score_evidence,source_checked_at=excluded.source_checked_at;

